        ".netra-dev-transcript {",
        "    display: flex;",
        "    flex-direction: column;",
        "    gap: 1px;",
        "    background: rgba(0, 0, 0, 0.18);",
        "    border-radius: 8px;",
        "    padding: 6px 10px;",
        "}",
