        "    background: linear-gradient(180deg, #3a3d49 0%, #2c2f3a 100%);",
        "    color: #ebedf2;",
        "    border: 1px solid rgba(255, 255, 255, 0.08);",
        "    border-radius: 6px;",
        "    padding: 5px 10px;",
        "    font-size: 10.5px;",
        "    cursor: pointer;",
        "    font-family: inherit;",
