        ".netra-mic-meter-test em {",
        "    color: #aecbfa;",
        "    font-size: 10px;",
        "    font-style: italic;",
        "}",
        "",
        "/* R1 - Real-time graphs */",
        ".netra-dev-graphs {",
        "    display: flex;",
        "    flex-direction: column;",
        "    gap: 8px;",
        "}",
        ".netra-graph-card {",
        "    background: rgba(0, 0, 0, 0.25);",
        "    border: 1px solid rgba(255, 255, 255, 0.05);",
        "    border-radius: 8px;",
        "    padding: 8px 10px;",
        "}",
        ".netra-graph-title {",
        "    color: #9aa0a6;",
        "    font-size: 9.5px;",
        "    font-weight: 600;",
        "    letter-spacing: 0.08em;",
        "    margin-bottom: 4px;",
        "    text-transform: uppercase;",
        "}",
        ".netra-graph-sub {",
        "    color: #6b7178;",
